            session_id?: string;
            /** @description The W3C trace identifier of the action. */
            trace_id?: string;
            /**
             * Format: uuid
             * @description The action that led to this one.
             */
            parent_action_id?: string;
            /** @description The agent that asked this agent to act. */
            caller_agent_id?: string;
